import { supabase } from "@/integrations/supabase/client";

export interface WatchedItem {
  id: string;
  title: string;
  link?: string;
  severity: string;
  source_name: string;
  category: string;
  published_at: string;
  saved_at: string;
  notes?: string;
  ai_summary?: string | null;
}

export async function loadWatchlist(): Promise<WatchedItem[]> {
  const { data } = await supabase
    .from("saved_threats")
    .select("id,title,link,severity,source_name,category,published_at,saved_at,notes,ai_summary")
    .order("saved_at", { ascending: false });
  return (data ?? []) as WatchedItem[];
}

export function useWatchlist() {
  const add = async (item: Omit<WatchedItem, "saved_at">) => {
    const saved_at = new Date().toISOString();
    const { error } = await supabase
      .from("saved_threats")
      .upsert([{ ...item, saved_at }], { onConflict: "id", ignoreDuplicates: true });
    return !error;
  };
  const remove = async (id: string) => {
    await supabase.from("saved_threats").delete().eq("id", id);
  };
  const isWatched = async (id: string) => {
    const { count } = await supabase
      .from("saved_threats")
      .select("id", { count: "exact", head: true })
      .eq("id", id);
    return (count ?? 0) > 0;
  };
  return { add, remove, isWatched };
}
